insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Avocado', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "1ed5a9a980749701890f2900e4d2765f", "food_synergies": [{"paired_with": "Fat Type", "synergy": "Per 100g", "mechanism": "Properties"}, {"paired_with": "Oleic acid (monounsaturated)", "synergy": "~10g", "mechanism": "Anti-inflammatory; stable; integrates into cell membranes without oxidative stress"}, {"paired_with": "Palmitic acid (saturated)", "synergy": "~2.1g", "mechanism": "Neutral to slightly pro-inflammatory at high intake; well within safe range here"}, {"paired_with": "Linoleic acid (omega-6)", "synergy": "~1.7g", "mechanism": "Low relative to total fat \u2014 not a seed-oil omega-6 concern"}, {"paired_with": "Alpha-linolenic acid (omega-3)", "synergy": "~0.11g", "mechanism": "ALA; minimal EPA/DHA conversion"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs", "synergy": "Fat-soluble vitamin absorption", "mechanism": "Avocado''s monounsaturated fat acts as a carrier for eggs'' fat-soluble vitamins (A, D, E, K) \u2014 fat must be present for these vitamins to absorb; co-ingestion substantially increases their bioavailability"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Polyphenol bioavailability", "mechanism": "Avocado fat dramatically increases the absorption of blueberries'' fat-soluble phytonutrients (beta-carotene, lutein, zeaxanthin); one of the best-evidenced food pairings for nutrient bioavailability"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Anti-inflammatory fat synergy", "mechanism": "Monounsaturated fat (avocado) + EPA/DHA (salmon) together cover the full anti-inflammatory lipid spectrum; zero glucose impact; complementary fat profiles with no overlapping risks"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast", "synergy": "Satiety extension", "mechanism": "Fat slows gastric emptying and prolongs satiety from lean protein; potassium from avocado supports muscle recovery and electrolyte balance after training"}], "dosage_guidance": "> [!info] Calorie density is the main consideration\n> **Optimal per meal: \u00bd avocado (75\u2013100g)**\n> - Provides 120\u2013160 calories, 5\u20136.7g fibre, and the full micronutrient benefit\n> - A whole avocado (200g) = ~320 calories, predominantly fat \u2014 appropriate on higher-calorie days or as the primary fat source for a meal\n>\n> **No cholesterol** \u2014 avocado contains no dietary cholesterol whatsoever. Saturated fat is low (2.1g/100g) \u2014 the primary fat is oleic acid, which does not raise LDL meaningfully and may improve the LDL-to-HDL ratio.\n>\n> **No upper limit concern** beyond total calorie budget. Unlike seed oils, avocado fat does not carry oxidative stress, pro-inflammatory omega-6 load, or processing-related compounds.\n>\n> **Ripening:** avocados ripen at room temperature (2\u20135 days from firm). Refrigerate once ripe to extend by 2\u20133 days. The fat profile shifts slightly toward more monounsaturated fat as the fruit ripens \u2014 eat at peak ripeness.\n\n---", "good_energy_relevance": "Avocado is one of three foods in the vault (alongside oats and blueberries) that contributes meaningfully to the 50g/day fibre target \u2014 100g provides 6.7g fibre, the highest of any commonly eaten fatty food. The oleic acid integrates into mitochondrial membranes without the oxidative stress that polyunsaturated seed oils generate. The fat content makes avocado one of the most effective glucose-blunting additions to any meal.\n\n**Good Energy daily targets contribution (per 100g):**\n- Fibre: 6.7g of 50g target (13%)\n- Omega-3: 110mg of 2,000mg target (ALA, minimal)\n- Antioxidants: moderate (vitamin E, lutein, zeaxanthin, glutathione \u2014 richest fruit source of glutathione)\n- Probiotics: none\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Banana', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "012b1fd3699dc97df71171e8bb9f35ef", "nutrient": "Amount", "calcium": 5.9, "iron": 0.3, "potassium": 422, "sodium": 1.2}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Black Beans', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "de961385f4ddff2c378530e5a105f1bd", "nutrient": "Amount", "calcium": 3.5, "potassium": 50, "sodium": 125}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Blueberries', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "d949f9480fa8f9ba8e31935dc891734a", "food_synergies": [{"paired_with": "Compound", "synergy": "Per 100g", "mechanism": "Key Actions"}, {"paired_with": "Total anthocyanins", "synergy": "~165mg", "mechanism": "PGC-1\u03b1 activation; anti-inflammatory; neuroprotective"}, {"paired_with": "Quercetin", "synergy": "~7.7mg", "mechanism": "Anti-inflammatory; antiviral; mast cell stabiliser"}, {"paired_with": "Myricetin", "synergy": "~5.3mg", "mechanism": "Anti-inflammatory; anticancer; neuroprotective"}, {"paired_with": "Chlorogenic acid", "synergy": "~9.8mg", "mechanism": "Anti-glycaemic; antioxidant; liver protective"}, {"paired_with": "Pterostilbene", "synergy": "trace", "mechanism": "Resveratrol analogue; higher bioavailability; epigenetic effects"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado", "synergy": "Fat-soluble phytonutrient absorption", "mechanism": "Avocado''s monounsaturated fat significantly increases bioavailability of blueberries'' fat-soluble polyphenols (beta-carotene, lutein); the absorption of polyphenols generally improves substantially when co-ingested with dietary fat"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Double anti-glycaemic effect", "mechanism": "Beta-glucan (oats) + anthocyanins (blueberries) independently blunt glucose absorption; together the effect is additive; the combination is one of the most evidence-backed breakfast choices for metabolic health"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Brain health synergy", "mechanism": "DHA (salmon) provides structural substrate for neuronal membranes while anthocyanins (blueberries) reduce neuroinflammation and stimulate BDNF \u2014 synergistic for neuroplasticity and cognitive function"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs", "synergy": "Post-training recovery pair", "mechanism": "Anthocyanins reduce exercise-induced oxidative stress; egg protein and leucine drive muscle protein synthesis \u2014 a complementary recovery combination"}], "dosage_guidance": "> [!info] Optimal range and practical notes\n> **Optimal: 80\u2013150g per day**\n> - Below 80g: anthocyanin dose falls below levels used in most cognitive and mitochondrial benefit studies\n> - 80\u2013150g is the functional range for polyphenol benefit without excessive natural sugar load\n> - Above 150g: natural sugars accumulate (9.96g sugar per 100g); diminishing returns on antioxidant benefit per calorie\n>\n> **Wild blueberries:** 2\u20133\u00d7 higher anthocyanin content than cultivated (smaller berries, more skin per gram, deeper colour). Specifically superior for cognitive and mitochondrial applications if available.\n>\n> **Frozen = equally nutritious:** blueberries are frozen at peak ripeness, which preserves anthocyanin content. Out-of-season fresh blueberries are often lower in anthocyanins than frozen. No meaningful nutritional reason to prefer fresh unless in season.\n>\n> **No upper limit concern** for healthy individuals. Blueberries are essentially a free food from a calorie and glycaemic standpoint \u2014 the natural sugar is buffered by fibre and by the anti-glycaemic effect of the anthocyanins themselves.\n\n---", "good_energy_relevance": "Despite containing natural sugars (9.96g/100g), blueberries have a moderate GI (53) and a meaningful anti-glycaemic effect \u2014 their anthocyanins inhibit alpha-glucosidase (the enzyme that breaks down complex carbohydrates into glucose), independently reducing post-meal glucose. Long-term studies show blueberry consumption improves insulin sensitivity. The PGC-1\u03b1 activation is the direct mitochondrial link \u2014 making blueberries one of the few foods that supports all three of Means'' primary targets simultaneously: glucose management, mitochondrial health, and antioxidant protection.\n\n**Good Energy daily targets contribution (per 80g):**\n- Fibre: 1.9g of 50g target (4%)\n- Omega-3: 46mg of 2,000mg target (ALA, trace)\n- Antioxidants: high (anthocyanins, quercetin, chlorogenic acid)\n- Probiotics: none (but polyphenols act as prebiotics \u2014 selectively feeding beneficial gut bacteria)\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Broccoli', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "36f4d3051ce6a99306c0f58ef0d0d49f"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Chia Seeds', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "5be887d0a8297cb21093e3105cdccf21", "food_synergies": [{"paired_with": "Fat Type", "synergy": "Per 100g", "mechanism": "Properties"}, {"paired_with": "ALA (omega-3)", "synergy": "~17.8g", "mechanism": "Plant-based omega-3; highest of any common food; converts to EPA/DHA at ~5\u201310% efficiency"}, {"paired_with": "Linoleic acid (omega-6)", "synergy": "~5.8g", "mechanism": "Omega-6 content is lower relative to omega-3 than almost any plant food; omega-6:omega-3 ratio ~0.3:1 \u2014 exceptional"}, {"paired_with": "Palmitic acid (saturated)", "synergy": "~3.3g", "mechanism": "Neutral at this intake level"}, {"paired_with": "Fibre Type", "synergy": "Per 100g", "mechanism": "Role"}, {"paired_with": "Soluble (mucilaginous)", "synergy": "~14\u201316g", "mechanism": "Forms a thick gel when wet; slows gastric emptying; dramatically blunts glucose absorption; feeds gut bacteria"}, {"paired_with": "Insoluble", "synergy": "~18\u201320g", "mechanism": "Increases stool bulk; feeds different microbial populations"}, {"paired_with": "**Total**", "synergy": "**34.4g**", "mechanism": "**69% of the Good Energy 50g/day target in 100g \u2014 highest of any common food**"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Greek Yogurt", "synergy": "Synbiotic (prebiotic + probiotic)", "mechanism": "Chia''s soluble fibre feeds the live bacterial cultures in Greek yogurt \u2014 creating a highly gut-optimised combination; also dramatically increases satiety of the yogurt"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Fibre amplification", "mechanism": "Combining chia and oats in one meal (overnight oats) pushes the total fibre well above 15g per meal \u2014 one of the most effective single-meal gut microbiome inputs"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Antioxidant + prebiotic", "mechanism": "Blueberry polyphenols and chia fibre together provide both prebiotic substrate and antioxidant signalling to the gut microbiome"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Omega-3 complementarity", "mechanism": "Chia provides ALA (structural precursor); salmon provides EPA+DHA (active forms) \u2014 together they cover both plant and marine omega-3 pathways"}], "dosage_guidance": "> [!info] Small volume, high impact\n> **Optimal: 2\u20133 tablespoons (24\u201336g) per day**\n> - 2 tablespoons: 8.3g fibre, 4,279mg ALA \u2014 a meaningful daily contribution\n> - 3 tablespoons: 12.4g fibre \u2014 covers ~25% of the 50g/day target alone\n>\n> **Hydration:** chia seeds absorb up to 12\u00d7 their weight in water. Consuming dry chia seeds without adequate liquid can cause an uncomfortable gel mass in the gut. Always soak in liquid for at least 10\u201315 minutes, or mix into yogurt, oats, or a smoothie.\n>\n> **Introducing gradually:** the very high fibre content can cause gas and bloating if intake jumps suddenly. Build up from 1 tablespoon over 1\u20132 weeks.\n>\n> **No upper limit concern** from a toxicity standpoint, but above 4\u20135 tablespoons the calorie contribution (486 cal/100g) becomes significant \u2014 chia is calorie-dense by weight.\n\n---", "good_energy_relevance": "Chia seeds are the single most fibre-dense addition to the food library \u2014 2 tablespoons adds 8.3g fibre with almost no glucose impact. The mucilaginous gel directly slows gastric emptying and glucose absorption, making it a powerful glucose-blunting addition to any carbohydrate-containing meal. The omega-3:omega-6 ratio (~0.3:1) is the most favourable of any common plant food, actively countering the omega-6 overload that most people carry from seed oil consumption.\n\n**Good Energy daily targets contribution (per 24g / 2 tbsp):**\n- Fibre: 8.3g of 50g target (17%)\n- Omega-3: 4,279mg ALA (converts to ~200\u2013400mg EPA/DHA)\n- Antioxidants: moderate (quercetin, kaempferol, chlorogenic acid)\n- Probiotics: none (but soluble fibre is a highly effective prebiotic)\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Chicken Breast', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "b9da199ea2e92f1726e0ef70d350ca15", "food_synergies": [{"paired_with": "Amino Acid", "synergy": "Per 100g", "mechanism": "Sports Relevance"}, {"paired_with": "Leucine", "synergy": "2.47g", "mechanism": "Highest of common foods \u2014 primary mTOR trigger for MPS"}, {"paired_with": "Lysine", "synergy": "2.67g", "mechanism": "Collagen synthesis; carnitine production"}, {"paired_with": "Isoleucine", "synergy": "1.43g", "mechanism": "BCAA; glucose uptake into muscle during exercise"}, {"paired_with": "Valine", "synergy": "1.49g", "mechanism": "BCAA; muscle glycogen sparing"}, {"paired_with": "Threonine", "synergy": "1.35g", "mechanism": "Collagen and elastin; immune function"}, {"paired_with": "Phenylalanine", "synergy": "1.26g", "mechanism": "Tyrosine \u2192 dopamine, adrenaline, thyroid hormones"}, {"paired_with": "Methionine", "synergy": "0.89g", "mechanism": "Glutathione synthesis; SAMe for methylation"}, {"paired_with": "Tryptophan", "synergy": "0.38g", "mechanism": "Serotonin precursor; sleep regulation"}, {"paired_with": "Histidine", "synergy": "0.96g", "mechanism": "Carnosine synthesis; intramuscular buffering"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado", "synergy": "Satiety + vitamin absorption", "mechanism": "Avocado''s fat slows gastric emptying, extending satiety from lean protein; monounsaturated fat also carries fat-soluble vitamins and potassium supports muscle recovery"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Antioxidant cover", "mechanism": "High protein throughput generates oxidative byproducts; anthocyanins counteract exercise-induced oxidative stress alongside protein-driven tissue repair"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Complementary fat profile", "mechanism": "Alternating chicken (very high leucine, lean) and salmon (omega-3 rich) across the week provides complementary nutrients neither delivers alone"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Nutrient timing pair", "mechanism": "Oats 2\u20133 hours pre-training for sustained glycogen; chicken post-training for MPS \u2014 the classic nutrient timing combination"}], "dosage_guidance": "> [!info] How much per meal and per day?\n> **Optimal per meal: 150\u2013200g cooked** \u2014 provides 46\u201362g protein and clears the leucine threshold reliably\n>\n> **Diminishing returns above 300g per sitting:** muscle protein synthesis does not scale linearly with protein dose; the excess is oxidised for energy or converted to urea, not converted to muscle tissue. Two moderate meals are more effective than one very large serving.\n>\n> **Weekly variety:** chicken should not be the only protein source. Aim for 2\u20133 salmon servings per week for omega-3 balance \u2014 chicken provides almost none (60mg/100g vs. salmon''s 1,800mg). Eggs complement chicken by adding choline and fat-soluble vitamins that chicken lacks.\n>\n> **No cholesterol concern:** 85mg per 100g is low relative to eggs (372mg/100g); chicken breast is one of the most lipid-benign protein sources available.\n\n---", "good_energy_relevance": "Zero glycaemic impact. High protein density supports muscle protein synthesis after resistance training \u2014 muscle is the primary tissue for glucose disposal, making lean mass directly protective against insulin resistance. The niacin content makes chicken breast one of the best dietary sources of NAD+ precursors.\n\n**Good Energy daily targets contribution (per 150g):**\n- Fibre: 0g of 50g target\n- Omega-3: 90mg of 2,000mg target\n- Antioxidants: low\n- Probiotics: none\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Chickpeas', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "41e3831e65339d30339215167401d9fd", "nutrient": "Amount", "calcium": 40, "iron": 1.5, "potassium": 175, "sodium": 0}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
