insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Cottage Cheese', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "439d364c3557b6e6228fef299d9475cd", "nutrient": "Amount", "calcium": 250, "iron": 0.2, "potassium": 200, "sodium": 880}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Eggs', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "d11927e68e42d1554ab81ef379312404", "food_synergies": [{"paired_with": "Amino Acid", "synergy": "Per 100g", "mechanism": "Sports Relevance"}, {"paired_with": "Leucine", "synergy": "1.09g", "mechanism": "Primary mTOR activator \u2014 triggers muscle protein synthesis"}, {"paired_with": "Lysine", "synergy": "0.91g", "mechanism": "Collagen synthesis; carnitine production for fat metabolism"}, {"paired_with": "Phenylalanine", "synergy": "0.68g", "mechanism": "Precursor to dopamine, adrenaline, and thyroid hormones"}, {"paired_with": "Valine", "synergy": "0.77g", "mechanism": "BCAA; muscle glycogen sparing during endurance work"}, {"paired_with": "Threonine", "synergy": "0.56g", "mechanism": "Immune function; collagen and elastin production"}, {"paired_with": "Isoleucine", "synergy": "0.54g", "mechanism": "BCAA; glucose uptake into muscle during exercise"}, {"paired_with": "Histidine", "synergy": "0.30g", "mechanism": "Carnosine synthesis; intramuscular acid buffering"}, {"paired_with": "Methionine", "synergy": "0.38g", "mechanism": "Glutathione synthesis; methylation reactions"}, {"paired_with": "Tryptophan", "synergy": "0.17g", "mechanism": "Serotonin precursor; sleep quality regulation"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Glucose blunting", "mechanism": "Egg fat and protein slows gastric emptying \u2014 significantly reduces the glucose spike from oat carbohydrates when eaten first or together"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado", "synergy": "Fat-soluble vitamin absorption", "mechanism": "Avocado''s monounsaturated fat acts as a carrier for eggs'' fat-soluble vitamins (A, D, E, K) \u2014 co-ingestion substantially improves absorption"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Choline + DHA synergy", "mechanism": "Dietary choline and DHA combine to form phosphatidylcholine \u2014 the primary structural phospholipid of mitochondrial and neuronal membranes; eating both maximises substrate availability"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Antioxidant cover for training recovery", "mechanism": "Anthocyanins reduce exercise-induced oxidative stress while egg protein drives tissue repair \u2014 an effective post-training pairing"}], "dosage_guidance": "> [!warning] Cholesterol \u2014 the nuanced picture\n> One large egg contains **~186mg dietary cholesterol** \u2014 historically flagged under the old <300mg/day guideline.\n>\n> The current picture is more nuanced:\n> - **~75% of people are hypo-responders** \u2014 dietary cholesterol has minimal effect on their LDL; the liver compensates by producing less of its own\n> - **~25% of people are hyper-responders** \u2014 dietary cholesterol does raise LDL meaningfully; if this is you, eggs warrant closer monitoring\n> - The 2020 US Dietary Guidelines removed the specific 300mg/day cap, acknowledging individual variation\n> - **Saturated fat is a bigger LDL driver than dietary cholesterol** for most people \u2014 and eggs are moderate in saturated fat (3.1g/100g)\n>\n> **Practical range for active individuals: 2\u20134 whole eggs per day** is well-supported in the literature for metabolically healthy people. Monitor LDL particle size (not just total LDL) and HDL if eating at the higher end \u2014 eggs tend to raise both, and the ratio often does not worsen.\n\n---", "good_energy_relevance": "Near-zero glycaemic impact. The fat and protein combination maximises satiety and slows gastric emptying, blunting the glucose spike from any carbohydrates eaten at the same meal. Choline is a structural component of cardiolipin \u2014 the phospholipid central to the inner mitochondrial membrane and efficient ATP production.\n\n**Good Energy daily targets contribution (per 2 eggs):**\n- Fibre: 0g of 50g target\n- Omega-3: 180mg of 2,000mg target\n- Antioxidants: moderate (lutein, zeaxanthin, selenium)\n- Probiotics: none\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Flaxseeds (Ground)', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "5d276c93a3e380e811c01f8d30fe00d2", "nutrient": "Amount", "calcium": 50, "iron": 0.75, "potassium": 125, "sodium": 0}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Greek Yogurt', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "a578aa7b2b5cf7152c24f450ce48c2d1", "food_synergies": [{"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Probiotic + prebiotic (synbiotic)", "mechanism": "Blueberry polyphenols act as prebiotics \u2014 selectively feeding the Lactobacillus and Bifidobacterium strains in the yogurt; this combination (probiotic + prebiotic = synbiotic) is more effective than either alone"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chia Seeds", "synergy": "Fibre + probiotic", "mechanism": "Chia seeds provide soluble fibre that feeds the probiotic cultures and slows the digestion of yogurt''s carbohydrates; also dramatically increases the satiety of the meal"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Prebiotic fibre amplification", "mechanism": "Beta-glucan from oats is one of the most effective prebiotic fibres for Lactobacillus and Bifidobacterium; mixing with yogurt creates a gut-optimised breakfast"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Walnuts", "synergy": "Polyphenol + probiotic", "mechanism": "Walnut polyphenols (ellagic acid) are metabolised by gut bacteria into urolithins \u2014 compounds with anti-inflammatory and mitochondrial effects only accessible via a healthy microbiome"}], "dosage_guidance": "> [!info] Daily probiotic servings\n> **Optimal: 150\u2013200g per serving; 1\u20132 servings per day**\n>\n> Casey Means recommends 3+ servings of fermented foods daily. Greek yogurt can cover 1\u20132 of these if eaten at breakfast and as a snack; the remainder can come from kimchi, sauerkraut, or kefir.\n>\n> **Lactose intolerance:** the straining process and fermentation reduce lactose content to ~3.2g per 100g (vs. 4.8g in regular milk). Many people with mild lactose intolerance tolerate Greek yogurt well. Severely intolerant individuals should trial a small portion first.\n>\n> **Upper limit:** no meaningful upper limit for metabolically healthy individuals. Large amounts (400g+) in one sitting add significant saturated fat and calories \u2014 spread across the day is more effective than one large dose for microbiome diversity.\n\n---", "good_energy_relevance": "The gut microbiome is the fourth root cause of metabolic dysfunction in the Good Energy framework (gut dysbiosis). Greek yogurt directly addresses this \u2014 the live cultures populate the gut, produce short-chain fatty acids (SCFAs), and improve the intestinal barrier that prevents endotoxins from triggering systemic inflammation. B12 supports mitochondrial energy production, and the low GI (11) means it causes almost no glucose perturbation.\n\n**Good Energy daily targets contribution (per 200g):**\n- Fibre: 0g of 50g target\n- Omega-3: 100mg of 2,000mg target\n- Antioxidants: low\n- Probiotics: \u2713 1 of 3 daily probiotic servings\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
