insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Kirkland Three Berry Blend', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "8ba18cbe6b5235cd223f21e6870c12cc", "food_synergies": [{"paired_with": "Berry", "synergy": "Primary Polyphenols", "mechanism": "Key Action"}, {"paired_with": "Blueberries", "synergy": "Delphinidin, cyanidin, petunidin, peonidin, malvidin glucosides", "mechanism": "PGC-1\u03b1 activation \u2192 mitochondrial biogenesis; crosses blood-brain barrier"}, {"paired_with": "Blackberries", "synergy": "Cyanidin-3-glucoside (highest of the three)", "mechanism": "Anti-inflammatory; neuroprotective; cardiovascular protection"}, {"paired_with": "Raspberries", "synergy": "Ellagic acid, raspberry ketones, quercetin", "mechanism": "Ellagic acid \u2192 urolithins (gut bacteria convert to mitochondrial activators); anti-inflammatory"}, {"paired_with": "Attribute", "synergy": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]] (100g)", "mechanism": "Three Berry Blend (100g)"}, {"paired_with": "Calories", "synergy": "57", "mechanism": "52"}, {"paired_with": "Fibre", "synergy": "2.4g", "mechanism": "3.5g"}, {"paired_with": "Vitamin C", "synergy": "9.7mg", "mechanism": "18mg"}, {"paired_with": "Anthocyanins", "synergy": "~165mg", "mechanism": "~200\u2013250mg (estimated)"}, {"paired_with": "GI", "synergy": "53", "mechanism": "45 (lower \u2014 blackberries and raspberries have lower GI)"}, {"paired_with": "Polyphenol diversity", "synergy": "Moderate", "mechanism": "High (three distinct profiles)"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Greek Yogurt", "synergy": "Synbiotic + polyphenol diversity", "mechanism": "Probiotic bacteria from yogurt convert raspberry ellagic acid into urolithins; the three-berry polyphenol mix selectively feeds more diverse microbial populations than a single berry"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Double anti-glycaemic", "mechanism": "Beta-glucan + combined berry anthocyanins; lower GI than oats + blueberries alone"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado", "synergy": "Fat-soluble phytonutrient absorption", "mechanism": "Avocado fat enhances absorption of fat-soluble carotenoids and polyphenols from all three berries"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chia Seeds", "synergy": "Fibre amplification + antioxidant cover", "mechanism": "Combined fibre exceeds 7g per serving \u2014 significant prebiotic dose; chia ALA + berry polyphenols are complementary anti-inflammatory inputs"}], "dosage_guidance": "> [!info] Same practical range as pure blueberries\n> **Optimal: 80\u2013150g per day**\n> - 80g delivers ~2.8g fibre, ~14mg vitamin C, and a meaningful polyphenol dose\n> - 120\u2013150g is appropriate when the blend is the primary fruit source for the day\n>\n> **Frozen from frozen:** no need to thaw before eating \u2014 frozen berries can be added directly to oats, yogurt, or a smoothie. Thawed berries soften quickly; use promptly after thawing.\n>\n> **No upper limit concern** for metabolically healthy individuals. Natural sugars (7.5g/100g) are well-buffered by fibre and the anti-glycaemic effects of the polyphenols.\n\n---", "good_energy_relevance": "The three-berry blend covers more polyphenol pathways simultaneously than any single berry \u2014 addressing the antioxidant attribute of the Good Energy framework more broadly. The ellagic acid from raspberries adds a urolithin production pathway (via gut bacteria) that pure blueberries do not provide. As a Costco staple kept frozen, it is one of the most practical high-antioxidant foods to have consistently on hand.\n\n**Good Energy daily targets contribution (per 80g):**\n- Fibre: 2.8g of 50g target (6%)\n- Omega-3: 72mg of 2,000mg target (trace ALA)\n- Antioxidants: high (multi-spectrum anthocyanins, ellagic acid, quercetin)\n- Probiotics: none (but polyphenols are prebiotics for diverse microbial populations)\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
