insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Oats', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "b4623daa51f06c6db1bab986302ae7bb", "food_synergies": [{"paired_with": "Fibre Type", "synergy": "Per 100g", "mechanism": "Role"}, {"paired_with": "Beta-glucan (soluble)", "synergy": "~5.7g", "mechanism": "Forms viscous gel; blunts glucose absorption; feeds Lactobacillus and Bifidobacterium; clinical evidence for LDL reduction"}, {"paired_with": "Insoluble fibre", "synergy": "~4.9g", "mechanism": "Increases stool bulk; transit time; feeds different gut bacteria"}, {"paired_with": "**Total fibre**", "synergy": "**10.6g**", "mechanism": "**22% of the Good Energy 50g/day target in 100g dry oats**"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs", "synergy": "Glucose blunting", "mechanism": "Eating eggs (protein + fat) before or with oats significantly blunts the glucose spike; the fat and protein slow gastric emptying and reduce the glycaemic response of the carbohydrate"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Double anti-glycaemic effect", "mechanism": "Beta-glucan (oats) + anthocyanins (blueberries) both independently reduce post-meal glucose; together the effect is additive; anthocyanins also activate PGC-1\u03b1 to improve mitochondrial use of the carbohydrate energy"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado / nut butter", "synergy": "Fat-mediated glucose dampening", "mechanism": "Additional fat further reduces glucose response; useful on rest days when the same carbohydrate load causes a larger spike"}, {"paired_with": "Pre-workout carbohydrate", "synergy": "Glycogen loading", "mechanism": "Eaten 2\u20133 hours before training, oats provide sustained glycogen without GI distress \u2014 a reliable pre-training fuel"}], "dosage_guidance": "> [!warning] Timing matters more than amount\n> **Optimal serving: 60\u201380g dry**\n> - 60g provides the beta-glucan threshold (~3.4g) and 40.6g carbs \u2014 sufficient pre-training fuel\n> - 80g provides more fibre (8.5g) but 54g carbs \u2014 more appropriate for heavy training days\n>\n> **Morning is strongly preferred:** glucose tolerance is highest in the morning; the same 60g oat portion causes a ~30% larger glucose spike when eaten in the evening vs. 7\u20138am. This is a circadian effect, not a food quality issue.\n>\n> **Not for low-carb or rest days** if carbohydrate is being reduced \u2014 60g dry = 40.6g carbs is a significant glucose load. On rest days, substitute a lower-carb option or reduce portion to 40g.\n>\n> **Avoid instant oats:** heat processing degrades beta-glucan structure, reducing the functional fibre dose. Rolled oats (5-minute) or steel-cut oats preserve the beta-glucan intact.\n\n---", "good_energy_relevance": "Oats contribute meaningfully to the Good Energy framework''s 50g/day fibre target \u2014 one of the highest among common foods. The beta-glucan feeds the gut microbiome that produces SCFAs, which independently improve insulin sensitivity and reduce gut inflammation. Moderate GI (55) combined with beta-glucan gel means the glucose response in practice is lower than the GI number implies \u2014 especially when combined with eggs.\n\n**Good Energy daily targets contribution (per 60g dry):**\n- Fibre: 6.4g of 50g target (13%)\n- Omega-3: 66mg of 2,000mg target (ALA, poorly converted)\n- Antioxidants: moderate (avenanthramides, manganese-SOD2)\n- Probiotics: none (but beta-glucan is a prebiotic that feeds probiotic bacteria)\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
