insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Vega Protein + Supergreens (Vanilla)', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "50366d5790835704f129ce225e18d6d3", "nutrient": "Amount", "calcium": 75, "iron": 5, "potassium": 75, "sodium": 320, "vitamin_a": 50, "vitamin_c": 6, "vitamin_k": 32}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Walnuts', 'general', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "8c29c488afd7c66aa97566cb824011d4", "compound": "Significance", "ellagic_acid": "Converted by gut bacteria to urolithins \u2014 compounds with anti-inflammatory, mitochondrial biogenesis, and muscle recovery effects only accessible via a healthy microbiome", "juglone": "Unique to walnuts; antimicrobial; anti-inflammatory", "melatonin": "One of the few dietary sources; supports circadian rhythm and sleep quality; also a potent mitochondrial antioxidant", "quercetin": "Anti-inflammatory; antiviral; mast cell stabiliser", "catechins": "Cardiovascular protective; antioxidant", "food_synergies": [{"paired_with": "Fat Type", "synergy": "Per 100g", "mechanism": "Properties"}, {"paired_with": "ALA (omega-3)", "synergy": "~9.1g", "mechanism": "Plant-based omega-3; converts to EPA/DHA at ~5\u201310%; highest omega-3 of any nut"}, {"paired_with": "Linoleic acid (omega-6)", "synergy": "~38.1g", "mechanism": "Omega-6:omega-3 ratio ~4:1 \u2014 the best ratio of any nut; still high in absolute terms"}, {"paired_with": "Oleic acid (monounsaturated)", "synergy": "~8.9g", "mechanism": "Anti-inflammatory; stable"}, {"paired_with": "Saturated fat", "synergy": "6.1g", "mechanism": "Moderate; not a significant concern at typical serving sizes"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Greek Yogurt", "synergy": "Urolithin production", "mechanism": "Walnut ellagic acid is metabolised into urolithins by the gut bacteria present in Greek yogurt; eating walnuts alongside a probiotic source maximises the chance of complete conversion"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Dual polyphenol synergy", "mechanism": "Walnut polyphenols (ellagic acid, catechins) + blueberry anthocyanins act through complementary anti-inflammatory and neuroprotective pathways; combined, they represent the most polyphenol-dense snack combination in the vault"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Satiety + glucose management", "mechanism": "Walnut fat dramatically slows gastric emptying; adding walnuts to oats reduces the glucose spike and extends satiety well past the meal"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Omega-3 complementarity", "mechanism": "ALA (walnuts) + EPA/DHA (salmon) \u2014 plant and marine omega-3 together provide broader metabolic coverage than either alone"}], "dosage_guidance": "> [!info] Optimal portion and timing\n> **Optimal: 28\u201330g per day (~15 walnut halves)**\n> - 30g provides ~2.7g ALA omega-3, 2g fibre, and a meaningful polyphenol dose\n> - The majority of clinical benefit studies used 28\u201342g/day\n> - Above 60g/day, the high calorie density (654 cal/100g) and absolute omega-6 content become meaningful constraints\n>\n> **Timing:** walnuts contain melatonin \u2014 eating them as an evening snack may subtly support sleep onset. There is no strong evidence for a specific optimal timing for the other benefits.\n>\n> **Raw vs. roasted:** raw or lightly roasted walnuts preserve polyphenol content better than heavily roasted. Avoid walnuts roasted in seed oils or salted. Dry-roasted or raw are the best options.\n>\n> **Storage:** walnuts go rancid quickly (high PUFA content oxidises at room temperature). Store in an airtight container in the refrigerator or freezer; use within 3 months of opening.\n\n---", "good_energy_relevance": "Walnuts are the most polyphenol-rich nut \u2014 and the only nut with a meaningful omega-3 contribution. They directly address three of Means'' five trackable attributes: omega-3 (ALA), antioxidants (ellagic acid, catechins, melatonin), and micronutrient density (magnesium, copper, B6, folate). The ellagic acid \u2192 urolithin pathway connects walnut consumption to both gut microbiome health and mitochondrial biogenesis \u2014 a rare dual benefit.\n\n**Good Energy daily targets contribution (per 30g):**\n- Fibre: 2.0g of 50g target (4%)\n- Omega-3: 2,724mg ALA (converts to ~136\u2013272mg EPA/DHA)\n- Antioxidants: high (ellagic acid, catechins, melatonin, quercetin)\n- Probiotics: none (but ellagic acid feeds probiotic bacteria)\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;